:host {
  display: block;
  min-height: 100%;
  min-width: 0;
}

* {
  box-sizing: border-box;
}

.page {
  min-height: 100vh;
  min-width: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #07101d;
  color: #e5e7eb;
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.card {
  width: min(100%,940px);
  min-width: 0;
  display: grid;
  gap: 16px;
  padding: 22px;
  border: 1px solid #29374d;
  border-radius: 18px;
  background: #0b1323;
  box-shadow: 0 24px 65px rgba(0,0,0,.32);
}

.card-header {
  min-width: 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
}

.card-header>div {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 5px;
  color: #bef264;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(21px,4vw,28px);
  line-height: 1.15;
}

.subtitle {
  max-width: 42ch;
  margin: 0;
  color: #94a3b8;
  font-size: 13px;
  line-height: 1.5;
}

.toolbar {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
}

.field {
  min-width: 0;
  display: grid;
  gap: 6px;
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 700;
}

.search-field {
  flex: 1 1 320px;
}

.size-field {
  flex: 0 1 130px;
}

.search-input,.page-size {
  width: 100%;
  min-width: 0;
  padding: 10px 11px;
  border: 1px solid #475569;
  border-radius: 10px;
  background: #070d19;
  color: #f8fafc;
  font: inherit;
}

.search-input::placeholder {
  color: #64748b;
}

.page-size {
  cursor: pointer;
}

.clear-selection,.footer button,.sort-id,.sort-name,.sort-role {
  border: 1px solid #475569;
  border-radius: 9px;
  background: #111c30;
  color: #e2e8f0;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
