  color: #94a3b8;
}

.footer {
  display: grid;
  grid-template-columns: auto minmax(0,1fr) auto;
  align-items: center;
  gap: 12px;
}

.footer button {
  padding: 9px 15px;
}

.page-info {
  text-align: center;
  color: #e2e8f0;
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width:680px) {
  .page {
    place-items: start center;
    padding: 12px;
  }

  .card {
    padding: 15px;
    border-radius: 14px;
  }

  .card-header {
    align-items: flex-start;
    flex-direction: column;
    gap: 7px;
  }

  .toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .search-field,.size-field {
    width: 100%;
    flex-basis: auto;
  }

  .clear-selection {
    width: 100%;
  }

  .summaries {
    align-items: flex-start;
    flex-direction: column;
  }

  .footer {
    gap: 8px;
  }

  .footer button {
    padding: 9px 11px;
  }

  .table {
    min-width: 620px;
  }
}
